insert into public.content_documents(key,draft,published) values ('about','{"fields":{"about-001":"Integrity","about-002":"We act with honesty, respect, and accountability in every interaction.","about-003":"Personal and community growth","about-004":"Individual growth and community development go hand in hand. We learn, share, and support one another.","about-005":"Positivity and initiative","about-006":"We approach challenges with a positive attitude and take proactive steps to make a difference.","about-007":"Participant safety and well-being","about-008":"Equal opportunity and non-discrimination","about-009":"Transparency and accountability","about-010":"Continuous improvement in program quality","about-011":"Alon Kaiser","about-012":"/images/founding-teacher-alon-placeholder.jpg","about-013":"James (Jim) Peters","about-014":"/images/founding-teacher-jim-placeholder.jpg","about-015":"Jon Best","about-016":"/images/founding-teacher-jon-placeholder.jpg","about-017":"Education Affairs","about-018":"Oversees student recruitment and monitors teaching and learning activities.","about-019":"Minh Tam","about-020":"/images/team-nhat-linh-placeholder.jpg","about-021":"Nhat Linh","about-022":"/images/team-nhat-linh-placeholder.jpg","about-023":"Tu Thu","about-024":"/images/team-tu-thu-placeholder.jpg","about-025":"Hong Thu","about-026":"/images/team-hong-thu-placeholder.jpg","about-027":"Thu Trang","about-028":"/images/team-thu-trang-placeholder.jpg","about-029":"Human Resources","about-030":"Coordinates volunteer and team recruitment, and creates opportunities for the community to connect.","about-031":"Quynh Nhu","about-032":"/images/team-hr-placeholder.jpg","about-033":"Tra My","about-034":"/images/team-tra-my-placeholder.jpg","about-035":"Hong Hanh","about-036":"/images/team-hong-hanh-placeholder.jpg","about-037":"Ngoc Giau","about-038":"/images/team-ngoc-giau-placeholder.jpg","about-039":"Communication and Outreach","about-040":"Manages media channels, partnerships, and fundraising outreach.","about-041":"Quang Vinh","about-042":"/images/founding-teacher-jim-placeholder.jpg","about-043":"Hong Nhung","about-044":"/images/team-hong-nhung-placeholder.jpg","about-045":"Thao Ngan","about-046":"/images/team-thao-ngan-placeholder.jpg","about-047":"My Huyen","about-048":"/images/team-my-huyen-placeholder.jpg","about-049":"Thuy Tien","about-050":"/images/team-thuy-tien-placeholder.jpg","about-051":"About ABVN","about-052":"Better English.","about-053":"Better Future.","about-054":"A Better Vietnam is a non-profit project founded in 2017. We support young Vietnamese people, especially those in underprivileged areas, through free one-to-one online English lessons with volunteer native-speaking teachers.","about-055":"#our-story","about-056":"Our story","about-057":"#our-programme","about-058":"Our programme","about-059":"#our-values","about-060":"Our values","about-061":"#our-people","about-062":"Our people","about-063":"/images/learning-community.jpg","about-064":"Students learning and sharing ideas together","about-065":"Our story","about-066":"Opportunity should not depend on where you begin.","about-067":"In many parts of Vietnam, talented and motivated young people are held back not by a lack of ambition, but by a lack of opportunity. Limited access to quality English education and global connections can become barriers to further study, employment, and personal growth.","about-068":"A Better Vietnam was created to help bridge that gap. What began as a small initiative connecting Vietnamese students with volunteer English speakers has grown into a global, youth-led community for learning, exchange, and growth.","about-069":"At its heart, ABVN is about more than English. It is about helping young people gain confidence, find their voice, and discover opportunities beyond their immediate environment.","about-070":"/images/english-classroom.jpg","about-071":"Students taking part in an English class","about-072":"Our mission","about-073":